var circles;
var bg;
var huu, sat, bri;

function setup() {
  createCanvas(800, 800);
  colorMode(HSB, 360, 100, 100, 100);
  pixelDensity(1);
  huu = random(360);
  sat = 20;
  bri = 90;
  bg = color(huu, sat, bri);
  background(bg);

  circles = [];

  const radius = width * 0.35;
  const maxRadius = radius * 0.5;

  // Pack a maximum of 1000 circles within a set radius
  for (let i = 0; i < 1000; i++) {
    const _maxRadius = random(random(0.75, 1)) ** 2 * maxRadius;
    let pos;
    let retryCount = 0;
		// Try to find a xy-coordinate within the radius that is not occupied by a circle
    do {
      pos = p5.Vector.fromAngle(random(TWO_PI) * 2).mult(
        (1 - random(random(1))) * radius
      );
      pos.z = 1;
      retryCount++;
      if (retryCount > 1000) {
        return;
      }
    } while (checkOverlapping(pos));

		// Grow the new circle by one until it overlaps with other circles (z is used as the radius)
    do {
      pos.z += 1;
    } while (
      circles.length > 0 &&
      pos.z < _maxRadius &&
      !checkOverlapping(pos, -20)
    );

    pos.z -= 1;
		// add new circle to circles
    circles.push(pos);
  }
}

function draw() {
  translate(width / 2, height / 2);
  noStroke();
  const scaler = 0.25;
  const noiseScaler = 0.01;
  const odd = frameCount % 2 === 1;
  const colorA = 0;
  const colorB = color(
    (huu + ((frameCount * scaler * 5) % 180)) % 360,
    sat + 30 - frameCount * scaler * 0.5,
    bri - 10 + frameCount * scaler * 0.5
  );
  circles.map((pos) => {
    blendMode(BLEND);
    fill(odd ? colorA : colorB);
    const r = pos.z - frameCount * scaler - (odd ? 0 : scaler);
    if (r < scaler) {
      return;
    }

    // Draw the circle
    circle(
      pos.x + random(-1, 1) * min(r * 0.25, 3),
      pos.y + random(-1, 1) * min(r * 0.25, 3) - frameCount * scaler * 1.5,
      r * 2
    );

    // Draw shadows
    blendMode(HARD_LIGHT);
    fill(0, 10);
    circle(pos.x + 3, pos.y + 2 - frameCount * scaler * 1.5, r * 2);
		fill(0,1);
    circle(
      pos.x + frameCount * scaler * 3 + random(-1, 1) * min(r * 0.25, 3),
      pos.y + frameCount * scaler * 2 + random(-1, 1) * min(r * 0.25, 3),
      r * 2
    );
  });
}

// Brute force check for overlapping
function checkOverlapping(pos, margin = 0) {
  return circles.some(
    (other) => dist(pos.x, pos.y, other.x, other.y) < pos.z + other.z + margin
  );
}
